    if (ISU_CD === "") {
        await $c.win.alert("[종목코드]를 선택하세요.");
        ($c.util.getComponent('ipt_ISU_CD') && $c.util.getComponent('ipt_ISU_CD').setFocus ? $c.util.getComponent('ipt_ISU_CD').setFocus() : ($c.util.getComponent('ipt_ISU_CD') && $c.util.getComponent('ipt_ISU_CD').focus ? $c.util.getComponent('ipt_ISU_CD').focus() : console.warn('[sdd] focus 대상 미해결: ipt_ISU_CD')));
        return;
    }
    if (($c.util.getComponent('cal_decisionDate').getValue() == null ? '' : String($c.util.getComponent('cal_decisionDate').getValue())) === '') {
        await $c.win.alert("[이사회결의일]을 입력하세요.");
