        return;
    }
    if (($c.util.getComponent('cal_beforeThreeDay').getValue() == null ? '' : String($c.util.getComponent('cal_beforeThreeDay').getValue())) === '') {
        await $c.win.alert("[납입일전 3거래일]을 입력하세요.");
        $c.util.getComponent("cal_beforeThreeDay").focus();
        return;
    }
    if (($c.util.getComponent('ipt_premiumRate').getValue() == null ? '' : String($c.util.getComponent('ipt_premiumRate').getValue())) === '' && ($c.util.getComponent('ipt_discountRate').getValue() == null ? '' : String($c.util.getComponent('ipt_discountRate').getValue())) === '') {
        await $c.win.alert("할증율 또는 할인율 둘중 하나 이상은 값을 입력해야합니다.");
        return;
    }
    const sDecisionDate = $c.util.getComponent('cal_decisionDate').getValue();
    const sBeforeThreeDay = $c.util.getComponent('cal_beforeThreeDay').getValue();
    const nextMonth = scwin.addMonthsToDate(sDecisionDate.substring(0, 4), sDecisionDate.substring(4, 6), sDecisionDate.substring(6, 8), 1);
    if (($c.util.getComponent('rd_sellIntval').getValue() === '0')) {
        if (nextMonth > sBeforeThreeDay) {
            await $c.win.alert("[이사회결의일 ~ 납입일전 3거래일] 간 간격이 1개월 미만입니다.");
            return;
        }
    } else {
        if (nextMonth <= sBeforeThreeDay) {
            await $c.win.alert("[이사회결의일 ~ 납입일전 3거래일] 간 간격이 1개월 이상입니다.");
            return;
